  "tpl.container_loading.name": { en: "Container loading", zh: "装柜报告", ar: "تحميل كونتينر" },
  "tpl.container_loading.desc": { en: "A container loaded: its number and seal, how it was packed and secured, with photos — signed by whoever supervised.", zh: "装柜记录：柜号和封条、装载与加固情况及照片——由监装人签字。", ar: "كونتينر اتحمّل: رقمه والسيل، اتحمّل واتربط إزاي، بالصور — بتوقيع اللي كان مشرف." },
  "tpl.shipment_update.name": { en: "Shipment status", zh: "货运状态", ar: "حالة شحنة" },
  "tpl.shipment_update.desc": { en: "Where a shipment is now, the vessel or flight, when it arrives, and anything holding it up.", zh: "货物当前位置、船名或航班、预计到达时间以及任何延误。", ar: "الشحنة فين دلوقتي، المركب ولا الطيارة، هتوصل إمتى، وإيه اللي معطّلها." },
  "tpl.damage_claim.name": { en: "Damage and claim", zh: "货损与索赔", ar: "تلف ومطالبة" },
  "tpl.damage_claim.desc": { en: "Goods that arrived damaged: what, how many, what they are worth, and the claim — against whom and where it stands.", zh: "到货受损：损坏物品、数量、价值以及索赔对象和进展。", ar: "بضاعة وصلت تالفة: إيه، وكام، وتسوى كام، والمطالبة — على مين ووصلت لفين." },
  "tpl.customs_clearance.name": { en: "Customs clearance", zh: "清关报告", ar: "تخليص جمركي" },
  "tpl.customs_clearance.desc": { en: "A shipment through customs: which papers are ready, the duties and fees, and where it stands.", zh: "货物清关：文件准备情况、关税和费用以及当前进展。", ar: "شحنة في الجمارك: أنهي ورق جاهز، الرسوم والجمارك، ووصلت لفين." },
  "tpl.service_visit.name": { en: "Service visit", zh: "维修服务报告", ar: "زيارة صيانة" },
  "tpl.service_visit.desc": { en: "A service call at a customer: the problem, the work done, the parts used, the result — signed by the customer.", zh: "上门服务：问题、所做工作、使用的备件和结果——由客户签字。", ar: "زيارة صيانة عند عميل: المشكلة، اتعمل إيه، قطع الغيار اللي اتركبت، والنتيجة — بتوقيع العميل." },
  "tpl.warranty_claim.name": { en: "Warranty claim", zh: "保修索赔", ar: "مطالبة ضمان" },
  "tpl.warranty_claim.desc": { en: "A fault under warranty: the machine, the fault, the likely cause, and whether it is covered — for management's decision.", zh: "保修期内的故障：机器、故障、可能原因以及是否在保修范围——由管理层决定。", ar: "عطل في الضمان: المكنة، العطل، السبب المحتمل، وهل يدخل في الضمان — والقرار للإدارة." },
  "tpl.customer_training.name": { en: "Customer training", zh: "客户培训", ar: "تدريب عميل" },
  "tpl.customer_training.desc": { en: "Operators trained at a customer: who attended, the topics covered, how they did — signed by the customer.", zh: "客户操作员培训：参加人员、培训内容和学员表现——由客户签字。", ar: "تدريب عمال عند عميل: مين حضر، اتدربوا على إيه، وعملوا إزاي — بتوقيع العميل." },
  "tpl.spare_parts_request.name": { en: "Spare parts request", zh: "备件申请", ar: "طلب قطع غيار" },
  "tpl.spare_parts_request.desc": { en: "Parts a customer needs: which and how many, how urgent, and who pays.", zh: "客户所需备件：名称、数量、紧急程度以及由谁付款。", ar: "قطع غيار العميل محتاجها: أنهي وكام، مستعجلة قد إيه، ومين هيدفع." },
  "tpl.trip_report.name": { en: "Trip report", zh: "出差报告", ar: "تقرير رحلة" },
  "tpl.trip_report.desc": { en: "A business trip from its first day to its last: where and why, the meetings, the results, the follow-ups — and your expenses from Finance.", zh: "从出发到返回的出差：地点和目的、会面、成果、后续跟进——以及财务中的你的费用。", ar: "رحلة شغل من أول يوم لآخر يوم: فين وليه، المقابلات، النتايج، المتابعات — ومصاريفك من المالية." },
  "tpl.delegation_visit.name": { en: "Delegation visit", zh: "来访接待报告", ar: "زيارة وفد" },
  "tpl.delegation_visit.desc": { en: "Visitors hosted from their first day to their last: who came, the program, what was discussed and agreed, the next steps.", zh: "从抵达到离开的来访接待：来访人员、日程、讨论与达成的事项及下一步。", ar: "زوار استقبلناهم من أول يوم لآخر يوم: مين جه، البرنامج، اتكلمنا واتفقنا على إيه، والخطوات الجاية." },
  "tpl.meeting_minutes.name": { en: "Meeting minutes", zh: "会议纪要", ar: "محضر اجتماع" },
  "tpl.meeting_minutes.desc": { en: "A meeting on record: who attended, the agenda, the discussion, and each decision with its owner and date.", zh: "会议记录：参会人员、议程、讨论以及每项决定的负责人和日期。", ar: "اجتماع متسجل: مين حضر، جدول الأعمال، النقاش، وكل قرار بمسؤوله وتاريخه." },
  "tpl.decision_log.name": { en: "Decision log", zh: "决策记录", ar: "سجل القرارات" },
  "tpl.decision_log.desc": { en: "Decisions taken, one per line: when, what, by whom and why — so nobody has to remember.", zh: "逐条记录的决定：时间、内容、决定人和原因——无需靠记忆。", ar: "القرارات اللي اتاخدت، كل قرار في سطر: إمتى، إيه، مين، وليه — عشان محدش يعتمد على الذاكرة." },

